@import "tailwindcss";

:root {
  --shell: #f6f8fc;
  --surface: #ffffff;
  --surface-read: #f2f6fc;
  --surface-hover: #eef3fb;
  --surface-sel: #c2dbff;
  --nav-sel: #d3e3fd;
  --nav-sel-text: #001d35;
  --searchbar: #eaf1fb;
  --searchbar-focus: #ffffff;
  --line: #e1e6ed;
  --line-strong: #c7cdd6;
  --ink-1: #1f1f1f;
  --ink-2: #444746;
  --ink-3: #5e6368;
  --accent: #0b57d0;
  --accent-hover: #0847a8;
  --accent-soft: #ecf3fe;
  --accent-ink: #001d35;
  --compose-btn: #c2e7ff;
  --star: #f4b400;
  --danger: #b3261e;
  --chip: #f1f3f4;
  --scrim: rgba(32, 33, 36, 0.5);
  --shadow-menu: 0 1px 3px rgba(60, 64, 67, 0.3), 0 4px 12px 4px rgba(60, 64, 67, 0.15);
  --shadow-compose: 0 8px 10px 1px rgba(0, 0, 0, 0.14), 0 3px 14px 2px rgba(0, 0, 0, 0.12), 0 5px 5px -3px rgba(0, 0, 0, 0.2);
  --row-shadow: inset 0 -1px 0 0 var(--line);
}

.dark {
  --shell: #0e1014;
  --surface: #17191d;
  --surface-read: #101215;
  --surface-hover: #1e2126;
  --surface-sel: #143a66;
  --nav-sel: #004a77;
  --nav-sel-text: #c2e7ff;
  --searchbar: #23262b;
  --searchbar-focus: #2b2e34;
  --line: #2a2d33;
  --line-strong: #3c4045;
  --ink-1: #e6e9ec;
  --ink-2: #c0c4c9;
  --ink-3: #8f959c;
  --accent: #a8c7fa;
  --accent-hover: #c3d8fb;
  --accent-soft: #1a2b45;
  --accent-ink: #d6e4ff;
  --compose-btn: #37588f;
  --star: #f4c145;
  --danger: #f2b8b5;
  --chip: #26292e;
  --scrim: rgba(0, 0, 0, 0.6);
  --shadow-menu: 0 1px 3px rgba(0, 0, 0, 0.5), 0 4px 12px 4px rgba(0, 0, 0, 0.35);
  --shadow-compose: 0 8px 10px 1px rgba(0, 0, 0, 0.4), 0 3px 14px 2px rgba(0, 0, 0, 0.35), 0 5px 5px -3px rgba(0, 0, 0, 0.5);
}

@theme inline {
  --color-shell: var(--shell);
  --color-surface: var(--surface);
  --color-surface-read: var(--surface-read);
  --color-surface-hover: var(--surface-hover);
  --color-surface-sel: var(--surface-sel);
  --color-nav-sel: var(--nav-sel);
  --color-nav-sel-text: var(--nav-sel-text);
  --color-searchbar: var(--searchbar);
  --color-searchbar-focus: var(--searchbar-focus);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-ink-1: var(--ink-1);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-soft: var(--accent-soft);
  --color-accent-ink: var(--accent-ink);
  --color-compose-btn: var(--compose-btn);
  --color-star: var(--star);
  --color-danger: var(--danger);
  --color-chip: var(--chip);
  --color-scrim: var(--scrim);
  --font-sans: "Google Sans Text", "Google Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

html,
body,
#root {
  height: 100%;
}

body {
  background: var(--shell);
  color: var(--ink-1);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior-y: none;
}

/* Thin, Gmail-like scrollbars */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--line-strong) transparent;
}
*::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
*::-webkit-scrollbar-thumb {
  background: var(--line-strong);
  border-radius: 8px;
}
*::-webkit-scrollbar-track {
  background: transparent;
}

/* Message body rendering */
.mail-body {
  font-size: 0.875rem;
  line-height: 1.55;
  color: var(--ink-1);
  word-break: break-word;
}
.mail-body p {
  margin: 0 0 0.85em;
}
.mail-body p:last-child {
  margin-bottom: 0;
}
.mail-body a {
  color: var(--accent);
  text-decoration: underline;
}
.mail-body ul,
.mail-body ol {
  margin: 0 0 0.85em;
  padding-left: 1.5em;
}
.mail-body ul {
  list-style: disc;
}
.mail-body ol {
  list-style: decimal;
}
.mail-body blockquote {
  border-left: 2px solid var(--line-strong);
  margin: 0 0 0.85em;
  padding-left: 0.85em;
  color: var(--ink-3);
}
.mail-body b,
.mail-body strong {
  font-weight: 600;
}
.mail-body .sig {
  color: var(--ink-3);
}
.mail-body table.card {
  border: 1px solid var(--line);
  border-radius: 8px;
  border-spacing: 0;
  margin: 0 0 0.85em;
  width: 100%;
}
.mail-body table.card td {
  padding: 6px 12px;
  border-bottom: 1px solid var(--line);
  font-size: 0.8125rem;
}
.mail-body table.card tr:last-child td {
  border-bottom: none;
}
.mail-body table.card td:first-child {
  color: var(--ink-3);
  white-space: nowrap;
  width: 1%;
  padding-right: 24px;
}

/* Compose editor */
.compose-editor {
  outline: none;
  min-height: 100%;
  font-size: 0.875rem;
  line-height: 1.55;
}
.compose-editor:empty::before {
  content: attr(data-placeholder);
  color: var(--ink-3);
  pointer-events: none;
}
.compose-editor a {
  color: var(--accent);
  text-decoration: underline;
}
.compose-editor ul {
  list-style: disc;
  padding-left: 1.5em;
}
.compose-editor ol {
  list-style: decimal;
  padding-left: 1.5em;
}
.compose-editor blockquote {
  border-left: 2px solid var(--line-strong);
  padding-left: 0.85em;
  color: var(--ink-3);
}

/* Animations */
@keyframes toast-in {
  from {
    transform: translateY(12px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes pop-in {
  from {
    opacity: 0;
    transform: scale(0.97);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes slide-in-left {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(0);
  }
}
@keyframes slide-in-right {
  from {
    transform: translateX(24px);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.anim-toast {
  animation: toast-in 0.15s ease-out;
}
.anim-fade {
  animation: fade-in 0.12s ease-out;
}
.anim-pop {
  animation: pop-in 0.12s ease-out;
}
.anim-drawer {
  animation: slide-in-left 0.18s cubic-bezier(0.2, 0, 0, 1);
}
.anim-panel {
  animation: slide-in-right 0.18s cubic-bezier(0.2, 0, 0, 1);
}
.anim-spin {
  animation: spin 0.8s linear infinite;
}

/* Hide checkbox/star column hover swap helpers */
@media (hover: hover) {
  .row-actions {
    display: none;
  }
  .group\/row:hover .row-actions {
    display: flex;
  }
  .group\/row:hover .row-meta {
    display: none;
  }
}

