import type { Attachment, AttachmentKind, Contact } from '../types'

export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(' ')
}

let idCounter = 0
export function uid(prefix = 'id'): string {
  idCounter += 1
  return `${prefix}_${Date.now().toString(36)}_${idCounter.toString(36)}`
}

const AVATAR_COLORS = [
  '#AB47BC', '#7E57C2', '#5C6BC0', '#1A73E8', '#00897B',
  '#43A047', '#F4511E', '#E53935', '#8D6E63', '#546E7A',
  '#D81B60', '#3949AB', '#039BE5', '#00ACC1', '#7CB342',
  '#FB8C00', '#6D4C41', '#C0CA33',
]

export function avatarColor(email: string): string {
  let hash = 0
  for (let i = 0; i < email.length; i++) {
    hash = (hash * 31 + email.charCodeAt(i)) | 0
  }
  return AVATAR_COLORS[Math.abs(hash) % AVATAR_COLORS.length]
}

export function initial(name: string): string {
  return (name.trim()[0] ?? '?').toUpperCase()
}

export function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

export const ATTACHMENT_META: Record<AttachmentKind, { label: string; color: string }> = {
  pdf: { label: 'PDF', color: '#EA4335' },
  image: { label: 'IMG', color: '#34A853' },
  sheet: { label: 'XLS', color: '#188038' },
  doc: { label: 'DOC', color: '#4285F4' },
  slides: { label: 'PPT', color: '#F9AB00' },
  zip: { label: 'ZIP', color: '#5F6368' },
  code: { label: 'SRC', color: '#9334E6' },
  video: { label: 'VID', color: '#E37400' },
  audio: { label: 'AUD', color: '#D01884' },
  calendar: { label: 'ICS', color: '#1967D2' },
}

export function downloadAttachment(att: Attachment): void {
  const content = [
    `${att.name}`,
    ``,
    `This is a demo attachment generated by Fable Mail.`,
    `Kind: ${att.kind}  ·  Reported size: ${formatSize(att.size)}`,
  ].join('\n')
  const blob = new Blob([content], { type: 'text/plain' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = att.name.replace(/\.[a-z0-9]+$/i, '') + '.txt'
  document.body.appendChild(a)
  a.click()
  a.remove()
  setTimeout(() => URL.revokeObjectURL(url), 5000)
}

export function isValidEmail(value: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
}

export function contactFromInput(value: string): Contact {
  const trimmed = value.trim().replace(/[,;]$/, '')
  const match = trimmed.match(/^(.*)<([^>]+)>$/)
  if (match) {
    return { name: match[1].trim() || match[2].trim(), email: match[2].trim() }
  }
  const namePart = trimmed.split('@')[0].replace(/[._-]+/g, ' ')
  const name = namePart.replace(/\b\w/g, (c) => c.toUpperCase())
  return { name, email: trimmed }
}

export function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

/** Convert plain text (double-newline paragraphs) into simple HTML. */
export function textToHtml(text: string): string {
  return text
    .split(/\n{2,}/)
    .map((p) => `<p>${escapeHtml(p.trim()).replace(/\n/g, '<br>')}</p>`)
    .join('')
}

export function htmlToText(html: string): string {
  const el = document.createElement('div')
  el.innerHTML = html
  return (el.textContent ?? '').replace(/\s+/g, ' ').trim()
}

export function snippetOf(html: string, max = 140): string {
  const text = html
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim()
  return text.length > max ? text.slice(0, max - 1) + '…' : text
}

export function pluralize(n: number, word: string): string {
  return `${n} ${word}${n === 1 ? '' : 's'}`
}

