const path = await saveScreenshot(await page.screenshot(), "debug2.png");
console.log(JSON.stringify({ path, url: page.url() }));
EOF

export PATH="$HOME/.nvm/versions/node/v24.14.1/bin:$HOME/Library/pnpm:$PATH" && dev-browser --headless --timeout 90 <<'EOF'
const page = await browser.getPage("main");
// restore minimized Quickdraws compose (click its header bar)
await page.locator("div", { hasText: /^Quickdraws$/ }).last().click();
await page.waitForTimeout(300);
await page.locator(".compose-editor").last().click();
await page.keyboard.type("Bringing 12 quickdraws Thursday.");
await page.getByTitle("Send (⌘Enter)").click();
await page.waitForTimeout(400);
await saveScreenshot(await page.screenshot(), "sent-toast.png");
await page.getByRole("button", { name: "Undo" }).click();
await page.waitForTimeout(400);
const path = await saveScreenshot(await page.screenshot(), "undo-send.png");
console.log(JSON.stringify({ path }));
EOF

export PATH="$HOME/.nvm/versions/node/v24.14.1/bin:$HOME/Library/pnpm:$PATH" && dev-browser --headless --timeout 40 <<'EOF'
const page = await browser.getPage("fresh");
await page.goto("http://localhost:9204");
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForTimeout(1200);
const title = await page.title();
const path = await saveScreenshot(await page.screenshot(), "final-fresh.png");
console.log(JSON.stringify({ title, path }));
EOF
